typedef struct TreeNode {
    int data;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

TreeNode* createNode(int value) {
    TreeNode* newNode = (TreeNode*)malloc(sizeof(TreeNode));
    if(newNode == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    newNode->data = value;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

void preorderTraversal(TreeNode* root) {
    if(root != NULL) {
        printf("%d ", root->data);  // 先访问根节点
        preorderTraversal(root->left);  // 然后遍历左子树
        preorderTraversal(root->right); // 最后遍历右子树
    }
}

void inorderTraversal(TreeNode* root) {
    if(root != NULL) {
        inorderTraversal(root->left);   // 先遍历左子树
        printf("%d ", root->data);    // 然后访问根节点
        inorderTraversal(root->right);  // 最后遍历右子树
    }
}

void postorderTraversal(TreeNode* root) {
    if(root != NULL) {
        postorderTraversal(root->left);  // 先遍历左子树
        postorderTraversal(root->right); // 然后遍历右子树
        printf("%d ", root->data);     // 最后访问根节点
    }
}

void freeTree(TreeNode* root) {
    if(root != NULL) {
        freeTree(root->left);
        freeTree(root->right);
        free(root);
    }
}

