    int V;
    AdjNode** array;
} Graph;

AdjNode* newAdjNode(int dest) {
    AdjNode* node = (AdjNode*)malloc(sizeof(AdjNode));
    node->dest = dest;
    node->next = NULL;
    return node;
}

Graph* createGraph(int V) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->V = V;
    graph->array = (AdjNode**)calloc(V, sizeof(AdjNode*));
    return graph;
}

void addEdge(Graph* graph, int src, int dest) {
    AdjNode* node = newAdjNode(dest);
    node->next = graph->array[src];
    graph->array[src] = node;

    node = newAdjNode(src);
    node->next = graph->array[dest];
    graph->array[dest] = node;
}

void bfs(Graph* graph, int start) {
    int* visited = (int*)calloc(graph->V, sizeof(int));
    int* queue = (int*)malloc(graph->V * sizeof(int));
    int front = 0, rear = 0;

    visited[start] = 1;
    queue[rear++] = start;

    while (front < rear) {
        int v = queue[front++];
        printf("%d ", v);

        for (AdjNode* temp = graph->array[v]; temp != NULL; temp = temp->next) {
            int adj = temp->dest;
            if (!visited[adj]) {
                visited[adj] = 1;
                queue[rear++] = adj;
            }
        }
    }
    printf("\n");

    free(queue);
    free(visited);
}

