#include <stdio.h>
#include <limits.h>

#define V 6

int minDistance(int dist[], int visited[]) {
    int min = INT_MAX, min_index = -1;
    for (int v = 0; v < V; v++) {
        if (!visited[v] && dist[v] <= min) {
            min = dist[v];
            min_index = v;
        }
    }
    return min_index;
}

void dijkstra(int graph[V][V], int src) {
    int dist[V];
    int visited[V] = {0};

    for (int i = 0; i < V; i++) {
        dist[i] = INT_MAX;
    }
    dist[src] = 0;

    for (int count = 0; count < V - 1; count++) {
        int u = minDistance(dist, visited);
        if (u == -1) break;
        visited[u] = 1;

        for (int v = 0; v < V; v++) {
            if (!visited[v] && graph[u][v] && dist[u] != INT_MAX && dist[u] + graph[u][v] < dist[v]) {
                dist[v] = dist[u] + graph[u][v];
            }
        }
    }

    printf("Vertex\tDistance from source\n");
    for (int i = 0; i < V; i++) {
        printf("%d\t%d\n", i, dist[i]);
    }
}

int main() {
    int graph[V][V] = {
        {0, 7, 9, 0, 0, 14},
        {7, 0, 10, 15, 0, 0},
        {9, 10, 0, 11, 0, 2},
        {0, 15, 11, 0, 6, 0},
        {0, 0, 0, 6, 0, 9},
        {14, 0, 2, 0, 9, 0}
    };
    dijkstra(graph, 0);
    return 0;
}

#include <stdio.h>
#include <limits.h>

#define V 4
#define INF 99999

void floydWarshall(int graph[V][V]) {
    int dist[V][V];

    for (int i = 0; i < V; i++) {
        for (int j = 0; j < V; j++) {
            dist[i][j] = graph[i][j];
        }
    }

    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }

    printf("All-pairs shortest path matrix:\n");
    for (int i = 0; i < V; i++) {
        for (int j = 0; j < V; j++) {
            if (dist[i][j] == INF) printf("INF ");
            else printf("%3d ", dist[i][j]);
        }
        printf("\n");
    }
}

int main() {
    int graph[V][V] = {
        {0,   5,  INF, 10},
        {INF, 0,   3, INF},
        {INF, INF, 0,   1},
        {INF, INF, INF, 0}
    };
    floydWarshall(graph);
    return 0;
}

#include <stdio.h>

typedef struct {
    int parent[100];
    int rank[100];
    int size;
} DisjointSet;

void dsuInit(DisjointSet* dsu, int n) {
    dsu->size = n;
    for (int i = 0; i < n; ++i) {
        dsu->parent[i] = i;
        dsu->rank[i] = 0;
    }
}

int dsuFind(DisjointSet* dsu, int x) {
    if (dsu->parent[x] != x) {
        dsu->parent[x] = dsuFind(dsu, dsu->parent[x]);
    }
    return dsu->parent[x];
}

void dsuUnion(DisjointSet* dsu, int x, int y) {
    int rootX = dsuFind(dsu, x);
    int rootY = dsuFind(dsu, y);
    if (rootX == rootY) return;

    if (dsu->rank[rootX] < dsu->rank[rootY]) {
        dsu->parent[rootX] = rootY;
    } else if (dsu->rank[rootX] > dsu->rank[rootY]) {
        dsu->parent[rootY] = rootX;
    } else {
        dsu->parent[rootY] = rootX;
        dsu->rank[rootX]++;
    }
}

int main() {
    DisjointSet dsu;
    dsuInit(&dsu, 6);
    dsuUnion(&dsu, 0, 1);
    dsuUnion(&dsu, 2, 3);
    dsuUnion(&dsu, 1, 2);

    printf("Find(3) = %d\n", dsuFind(&dsu, 3));
    printf("Find(5) = %d\n", dsuFind(&dsu, 5));
    return 0;
}

