typedef struct AdjNode {
    int dest;
    struct AdjNode* next;
} AdjNode;

typedef struct {
    int V;
    AdjNode** array;
} Graph;

AdjNode* newAdjNode(int dest) {
    AdjNode* node = (AdjNode*)malloc(sizeof(AdjNode));
    node->dest = dest;
    node->next = NULL;
    return node;
}

Graph* createGraph(int V) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->V = V;
    graph->array = (AdjNode**)calloc(V, sizeof(AdjNode*));
    return graph;
}

void addEdge(Graph* graph, int src, int dest) {
    AdjNode* node = newAdjNode(dest);
    node->next = graph->array[src];
    graph->array[src] = node;
}

void topologicalSort(Graph* graph) {
    int* indegree = (int*)calloc(graph->V, sizeof(int));
    for (int v = 0; v < graph->V; ++v) {
        for (AdjNode* temp = graph->array[v]; temp; temp = temp->next) {
            indegree[temp->dest]++;
        }
    }

    int* queue = (int*)malloc(graph->V * sizeof(int));
    int front = 0, rear = 0;
    for (int i = 0; i < graph->V; ++i) {
        if (indegree[i] == 0) queue[rear++] = i;
    }

    int count = 0;
    while (front < rear) {
        int v = queue[front++];
        printf("%d ", v);
        count++;
        for (AdjNode* temp = graph->array[v]; temp; temp = temp->next) {
            if (--indegree[temp->dest] == 0) {
                queue[rear++] = temp->dest;
            }
        }
    }
    printf("\n");

    if (count != graph->V) {
        printf("Graph has a cycle!\n");
    }

    free(queue);
    free(indegree);
}

int main() {
    Graph* graph = createGraph(6);
    addEdge(graph, 5, 2);
    addEdge(graph, 5, 0);
    addEdge(graph, 4, 0);
    addEdge(graph, 4, 1);
    addEdge(graph, 2, 3);
    addEdge(graph, 3, 1);

    printf("Topological order: ");
    topologicalSort(graph);
    return 0;
}

#include <stdio.h>
#include <string.h>

void buildLPS(const char* pattern, int m, int lps[]) {
    int len = 0;
    lps[0] = 0;
    int i = 1;
    while (i < m) {
        if (pattern[i] == pattern[len]) {
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i] = 0;
                i++;
            }
        }
    }
}

void kmpSearch(const char* text, const char* pattern) {
    int n = strlen(text);
    int m = strlen(pattern);
    int lps[m];
    buildLPS(pattern, m, lps);

    int i = 0, j = 0;
    while (i < n) {
        if (pattern[j] == text[i]) {
            i++;
            j++;
        }
        if (j == m) {
            printf("Found pattern at index %d\n", i - j);
            j = lps[j - 1];
        } else if (i < n && pattern[j] != text[i]) {
            if (j != 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
    }
}

int main() {
    const char* text = "ababcabcabababd";
    const char* pattern = "ababd";
    kmpSearch(text, pattern);
    return 0;
}

#include <stdio.h>

#define N 3

void matrixMultiply(int A[N][N], int B[N][N], int C[N][N], int n) {
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            C[i][j] = 0;
            for (int k = 0; k < n; ++k) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}

int main() {
    int A[N][N] = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };
    int B[N][N] = {
        {9, 8, 7},
        {6, 5, 4},
        {3, 2, 1}
    };
    int C[N][N];

    matrixMultiply(A, B, C, N);

    printf("Result matrix:\n");
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            printf("%4d", C[i][j]);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

#define N 3

void gaussianElimination(double a[N][N+1], int n) {
    for (int i = 0; i < n; ++i) {
        double pivot = a[i][i];
        for (int j = i; j <= n; ++j) {
            a[i][j] /= pivot;
        }
        for (int k = 0; k < n; ++k) {
            if (k != i) {
                double factor = a[k][i];
                for (int j = i; j <= n; ++j) {
                    a[k][j] -= factor * a[i][j];
                }
            }
        }
    }

    printf("Solution vector:\n");
    for (int i = 0; i < n; ++i) {
        printf("x%d = %.3f\n", i + 1, a[i][n]);
    }
}

int main() {
    double augmented[N][N+1] = {
        {2, 1, -1, 8},
        {-3, -1, 2, -11},
        {-2, 1, 2, -3}
    };
    gaussianElimination(augmented, N);
    return 0;
}

#include <stdio.h>
#include <string.h>

int lcsLength(const char* X, const char* Y) {
    int m = strlen(X);
    int n = strlen(Y);
    int dp[m + 1][n + 1];

    for (int i = 0; i <= m; ++i) {
        for (int j = 0; j <= n; ++j) {
            if (i == 0 || j == 0) dp[i][j] = 0;
            else if (X[i - 1] == Y[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
            else dp[i][j] = dp[i - 1][j] > dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1];
        }
    }
    return dp[m][n];
}

int main() {
