#include <stdio.h>

int knapSack(int capacity, int weights[], int values[], int n) {
    int dp[n + 1][capacity + 1];
    for (int i = 0; i <= n; ++i) {
        for (int w = 0; w <= capacity; ++w) {
            if (i == 0 || w == 0) dp[i][w] = 0;
            else if (weights[i - 1] <= w) {
                int include = values[i - 1] + dp[i - 1][w - weights[i - 1]];
                int exclude = dp[i - 1][w];
                dp[i][w] = include > exclude ? include : exclude;
            } else {
                dp[i][w] = dp[i - 1][w];
            }
        }
    }
    return dp[n][capacity];
}

int main() {
    int values[] = {60, 100, 120};
    int weights[] = {10, 20, 30};
    int capacity = 50;
    int n = sizeof(values) / sizeof(values[0]);
    printf("Max value = %d\n", knapSack(capacity, weights, values, n));
    return 0;
}

#include <stdio.h>

typedef struct {
    int size;
    int tree[100];
} Fenwick;

void fenwickInit(Fenwick* ft, int n) {
    ft->size = n;
    for (int i = 1; i <= n; ++i) ft->tree[i] = 0;
}

void fenwickUpdate(Fenwick* ft, int index, int value) {
    for (; index <= ft->size; index += index & -index) {
        ft->tree[index] += value;
    }
}

int fenwickQuery(Fenwick* ft, int index) {
    int sum = 0;
    for (; index > 0; index -= index & -index) {
        sum += ft->tree[index];
    }
    return sum;
}

int main() {
    Fenwick ft;
    fenwickInit(&ft, 8);
    int nums[] = {0, 1, 2, 3, 4, 5, 6, 7, 8}; // 1-based for convenience
    for (int i = 1; i <= 8; ++i) {
        fenwickUpdate(&ft, i, nums[i]);
    }
    printf("Prefix sum up to 5 = %d\n", fenwickQuery(&ft, 5));
    fenwickUpdate(&ft, 3, 5);
    printf("After update, prefix sum up to 5 = %d\n", fenwickQuery(&ft, 5));
    return 0;
}

#include <stdio.h>
#include <stdint.h>

uint64_t modPow(uint64_t base, uint64_t exp, uint64_t mod) {
    uint64_t result = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    printf("3^45 mod 1000000007 = %llu\n", (unsigned long long)modPow(3, 45, 1000000007));
    return 0;
}

