char* to_binary_str(uint32_t x, char *buf, size_t n) {
    if (n < 33) return NULL;
    for (int i = 31; i >= 0; --i) {
        buf[31-i] = (x & (1u << i)) ? '1' : '0';
    }
    buf[32] = '\0';
    return buf;
}

