    printf("Original array: ");
    printArray(arr, size);
    heapSort(arr, size);
    printf("Sorted array: ");
    printArray(arr, size);
    return 0;
}

#include <stdio.h>

void shellSort(int arr[], int size) {
    // 从size/2开始，逐步减小间隔
    for (int gap = size / 2; gap > 0; gap /= 2) {
        // 对每个间隔进行插入排序
        for (int i = gap; i < size; i++) {
            int temp = arr[i];
            int j;

            // 将arr[i]插入到正确位置
            for (j = i; j >= gap && arr[j - gap] > temp; j -= gap) {
                arr[j] = arr[j - gap];
            }
            arr[j] = temp;
        }
    }
}

void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

