    int arr[] = {64, 34, 25, 12, 22, 11, 90};
    int size = sizeof(arr) / sizeof(arr[0]);
    printf("Original array: ");
    printArray(arr, size);
    shellSort(arr, size);
    printf("Sorted array: ");
    printArray(arr, size);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void countingSort(int arr[], int size, int max_val) {
    // 创建计数数组
    int* count = (int*)calloc(max_val + 1, sizeof(int));
    int* output = (int*)malloc(size * sizeof(int));

    // 计算每个元素的出现次数
    for (int i = 0; i < size; i++)
        count[arr[i]]++;

    // 修改count数组，使其包含实际位置
    for (int i = 1; i <= max_val; i++)
        count[i] += count[i - 1];

    // 构建输出数组
    for (int i = size - 1; i >= 0; i--) {
        output[count[arr[i]] - 1] = arr[i];
        count[arr[i]]--;
    }

    // 复制输出数组到原数组
    for (int i = 0; i < size; i++)
        arr[i] = output[i];

    free(count);
    free(output);
}

void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

int main() {
    int arr[] = {4, 2, 2, 8, 3, 3, 1};
    int size = sizeof(arr) / sizeof(arr[0]);
    int max_val = 8; // 数组中的最大值
    printf("Original array: ");
    printArray(arr, size);
    countingSort(arr, size, max_val);
    printf("Sorted array: ");
    printArray(arr, size);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// 获取数组中的最大值
int getMax(int arr[], int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++)
        if (arr[i] > max)
            max = arr[i];
    return max;
}

// 对指定位数进行计数排序
void countSort(int arr[], int size, int exp) {
    int output[size];
    int count[10] = {0};

    // 计算每个数字的出现次数
    for (int i = 0; i < size; i++)
        count[(arr[i] / exp) % 10]++;

    // 修改count数组
    for (int i = 1; i < 10; i++)
        count[i] += count[i - 1];

    // 构建输出数组
    for (int i = size - 1; i >= 0; i--) {
        output[count[(arr[i] / exp) % 10] - 1] = arr[i];
        count[(arr[i] / exp) % 10]--;
    }

    // 复制输出数组到原数组
    for (int i = 0; i < size; i++)
        arr[i] = output[i];
}

void radixSort(int arr[], int size) {
    int max = getMax(arr, size);

    // 对每个位数进行计数排序
    for (int exp = 1; max / exp > 0; exp *= 10)
        countSort(arr, size, exp);
}

void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

int main() {
    int arr[] = {170, 45, 75, 90, 2, 802, 24, 66};
    int size = sizeof(arr) / sizeof(arr[0]);
    printf("Original array: ");
    printArray(arr, size);
    radixSort(arr, size);
    printf("Sorted array: ");
    printArray(arr, size);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

void sieve(int n, int *isPrime) {
    for (int i = 0; i <= n; ++i) isPrime[i] = 1;
    if (n >= 0) isPrime[0] = 0;
    if (n >= 1) isPrime[1] = 0;
    int limit = (int)sqrt((double)n);
    for (int p = 2; p <= limit; ++p) {
        if (isPrime[p]) {
            for (long long x = 1LL*p*p; x <= n; x += p) {
                isPrime[x] = 0;
            }
        }
    }
}

int main() {
    int n = 50;
    int *mark = (int*)calloc(n + 1, sizeof(int));
    sieve(n, mark);
    printf("Primes up to %d: ", n);
    for (int i = 2; i <= n; ++i) if (mark[i]) printf("%d ", i);
    printf("\n");
    free(mark);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

long long extgcd(long long a, long long b, long long *x, long long *y) {
    if (b == 0) { *x = 1; *y = 0; return a >= 0 ? a : -a; }
    long long x1, y1;
    long long g = extgcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return g;
}

// 返回a在模m意义下的逆元，不存在则返回-1
long long modInverse(long long a, long long m) {
    long long x, y;
    long long g = extgcd(a, m, &x, &y);
    if (g != 1) return -1;
    long long inv = (x % m + m) % m;
    return inv;
}

int main() {
    long long a = 17, m = 1000000007LL;
    long long inv = modInverse(a, m);
    if (inv == -1) printf("Inverse does not exist\n");
    else printf("inv(%lld) mod %lld = %lld\n", a, m, inv);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int min3(int a, int b, int c) { return a < b ? (a < c ? a : c) : (b < c ? b : c); }

int editDistance(const char *s, const char *t) {
    int m = (int)strlen(s), n = (int)strlen(t);
    int *dp = (int*)malloc((m + 1) * (n + 1) * sizeof(int));
    #define IDX(i,j) ((i)*(n+1) + (j))
    for (int i = 0; i <= m; ++i) dp[IDX(i,0)] = i;
    for (int j = 0; j <= n; ++j) dp[IDX(0,j)] = j;
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            int cost = s[i-1] == t[j-1] ? 0 : 1;
            dp[IDX(i,j)] = min3( dp[IDX(i-1,j)] + 1, dp[IDX(i,j-1)] + 1, dp[IDX(i-1,j-1)] + cost );
        }
    }
    int ans = dp[IDX(m,n)];
    free(dp);
    return ans;
}

int main() {
    const char *a = "kitten", *b = "sitting";
    printf("editDistance(%s, %s) = %d\n", a, b, editDistance(a,b));
    return 0;
}

#include <stdio.h>

int lower_bound_int(int *a, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (a[m] < x) l = m + 1; else r = m;
    }
    return l;
}

int lis_length(int *arr, int n) {
    if (n <= 0) return 0;
    int tails[10005]; // 简化：假设n<=10005
    int len = 0;
    for (int i = 0; i < n; ++i) {
        int pos = lower_bound_int(tails, len, arr[i]);
        tails[pos] = arr[i];
        if (pos == len) ++len;
    }
    return len;
}

int main() {
    int a[] = {10,9,2,5,3,7,101,18};
    int n = sizeof(a)/sizeof(a[0]);
    printf("LIS length = %d\n", lis_length(a,n));
    return 0;
}

#include <stdio.h>

void swap_i(int *a, int *b){int t=*a;*a=*b;*b=t;}
int partition_i(int a[], int l, int r){int x=a[r], i=l; for(int j=l;j<r;++j){ if(a[j]<=x){swap_i(&a[i],&a[j]);++i;}} swap_i(&a[i],&a[r]); return i;}
int quickselect(int a[], int l, int r, int k){ // k: 0-based index
    if(l==r) return a[l];
    int p = partition_i(a,l,r);
    if(k==p) return a[p];
    else if(k<p) return quickselect(a,l,p-1,k);
    else return quickselect(a,p+1,r,k);
}

int main(){
    int a[]={7,10,4,3,20,15}; int n=sizeof(a)/sizeof(a[0]); int k=3;
    int val = quickselect(a,0,n-1,k-1);
    printf("%d-th smallest = %d\n", k, val);
    return 0;
}

#include <stdio.h>
#include <limits.h>
#include <stdlib.h>

typedef struct { int u,v,w; } Edge;

void bellman_ford(int V, int E, Edge *edges, int src) {
    int *dist = (int*)malloc(V * sizeof(int));
    for (int i=0;i<V;++i) dist[i] = INT_MAX;
    dist[src] = 0;
    for (int i=1;i<=V-1;++i) {
        int updated = 0;
        for (int j=0;j<E;++j) {
            int u=edges[j].u, v=edges[j].v, w=edges[j].w;
            if (dist[u]!=INT_MAX && dist[u]+w<dist[v]) { dist[v]=dist[u]+w; updated=1; }
        }
        if (!updated) break;
    }
    int negCycle = 0;
    for (int j=0;j<E;++j) {
        int u=edges[j].u, v=edges[j].v, w=edges[j].w;
        if (dist[u]!=INT_MAX && dist[u]+w<dist[v]) { negCycle=1; break; }
    }
    if (negCycle) printf("Negative cycle detected\n");
    else {
        for (int i=0;i<V;++i) printf("dist[%d]=%d\n", i, dist[i]);
    }
    free(dist);
}

int main(){
    int V=5; Edge edges[]={{0,1,-1},{0,2,4},{1,2,3},{1,3,2},{1,4,2},{3,2,5},{3,1,1},{4,3,-3}};
    int E=sizeof(edges)/sizeof(edges[0]);
    bellman_ford(V,E,edges,0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct { int u,v,w; } Edge;

typedef struct { int parent; int rank; } DSU;

int dsu_find(DSU *dsu, int x){ return dsu[x].parent==x?x:(dsu[x].parent=dsu_find(dsu, dsu[x].parent)); }
void dsu_union(DSU *dsu, int a, int b){ a=dsu_find(dsu,a); b=dsu_find(dsu,b); if(a==b) return; if(dsu[a].rank<dsu[b].rank) dsu[a].parent=b; else if(dsu[a].rank>dsu[b].rank) dsu[b].parent=a; else { dsu[b].parent=a; dsu[a].rank++; }}

int cmp_edge(const void* A, const void* B){ const Edge* a=(const Edge*)A; const Edge* b=(const Edge*)B; return a->w - b->w; }

void kruskal(int V, int E, Edge *edges){
    qsort(edges, E, sizeof(Edge), cmp_edge);
    DSU *dsu = (DSU*)malloc(V*sizeof(DSU));
    for(int i=0;i<V;++i){ dsu[i].parent=i; dsu[i].rank=0; }

    int mst_w=0, cnt=0;
    for(int i=0;i<E && cnt<V-1;++i){ int u=edges[i].u, v=edges[i].v, w=edges[i].w;
        if(dsu_find(dsu,u)!=dsu_find(dsu,v)){ dsu_union(dsu,u,v); mst_w+=w; ++cnt; printf("(%d-%d) w=%d\n", u, v, w);} }
    if (cnt!=V-1) printf("Graph not connected\n"); else printf("MST weight = %d\n", mst_w);
    free(dsu);
}

int main(){
    int V=4; Edge edges[]={{0,1,10},{0,2,6},{0,3,5},{1,3,15},{2,3,4}}; int E=sizeof(edges)/sizeof(edges[0]);
    kruskal(V,E,edges);
    return 0;
}

#include <stdio.h>
#include <string.h>

void rabin_karp(const char *text, const char *pat){
    const int B=131, MOD=1000000007;
    int n=strlen(text), m=strlen(pat);
    if(m==0||m>n){ printf("No match\n"); return; }
    long long powB=1, hpat=0, hwin=0;
    for(int i=0;i<m-1;++i) powB = (powB * B) % MOD;
    for(int i=0;i<m;++i){ hpat=(hpat*B + (unsigned char)pat[i])%MOD; hwin=(hwin*B + (unsigned char)text[i])%MOD; }
    for(int i=0;i<=n-m;++i){
        if(hpat==hwin){ if(strncmp(text+i, pat, m)==0) printf("Match at index %d\n", i); }
        if(i<n-m){ hwin = ((hwin - (long long)(unsigned char)text[i]*powB)%MOD + MOD)%MOD; hwin = (hwin*B + (unsigned char)text[i+m])%MOD; }
    }
}

int main(){ rabin_karp("ababcabcabababd", "ababd"); return 0; }

#include <stdio.h>
#include <stdlib.h>

typedef struct { int n; int *t; } SegTree;

SegTree* seg_build(int *a, int n){ SegTree* s=(SegTree*)malloc(sizeof(SegTree)); s->n=n; s->t=(int*)calloc(4*n, sizeof(int));
    // build
    int build(int idx,int l,int r){ if(l==r){ s->t[idx]=a[l]; return s->t[idx]; } int m=(l+r)/2; int L=build(idx*2,l,m), R=build(idx*2+1,m+1,r); return s->t[idx]=L+R; }
    build(1,0,n-1); return s; }

int seg_query(SegTree* s,int idx,int l,int r,int ql,int qr){ if(ql>r||qr<l) return 0; if(ql<=l&&r<=qr) return s->t[idx]; int m=(l+r)/2; return seg_query(s,idx*2,l,m,ql,qr)+seg_query(s,idx*2+1,m+1,r,ql,qr);}

void seg_update(SegTree* s,int idx,int l,int r,int pos,int val){ if(l==r){ s->t[idx]=val; return; } int m=(l+r)/2; if(pos<=m) seg_update(s,idx*2,l,m,pos,val); else seg_update(s,idx*2+1,m+1,r,pos,val); s->t[idx]=s->t[idx*2]+s->t[idx*2+1]; }

int main(){ int a[]={1,3,5,7,9,11}; int n=sizeof(a)/sizeof(a[0]); SegTree* s=seg_build(a,n);
    printf("sum[1,3]=%d\n", seg_query(s,1,0,n-1,1,3)); seg_update(s,1,0,n-1,1,10); printf("after update, sum[1,3]=%d\n", seg_query(s,1,0,n-1,1,3)); free(s->t); free(s); return 0; }

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct { int *data; int top; int cap; } IntStack;

IntStack* stk_new(int cap){ IntStack* s=(IntStack*)malloc(sizeof(IntStack)); s->data=(int*)malloc(sizeof(int)*cap); s->top=-1; s->cap=cap; return s; }
void stk_free(IntStack* s){ if(!s) return; free(s->data); free(s); }
int stk_empty(IntStack* s){ return s->top<0; }
void stk_push(IntStack* s,int x){ if(s->top+1>=s->cap){ s->cap*=2; s->data=(int*)realloc(s->data,sizeof(int)*s->cap);} s->data[++s->top]=x; }
int stk_pop(IntStack* s){ return s->top<0? INT_MIN : s->data[s->top--]; }
int stk_top(IntStack* s){ return s->top<0? INT_MIN : s->data[s->top]; }

typedef struct { IntStack *val, *min; } MinStack;

MinStack* minstack_new(int cap){ MinStack* m=(MinStack*)malloc(sizeof(MinStack)); m->val=stk_new(cap); m->min=stk_new(cap); return m; }
void minstack_free(MinStack* m){ if(!m) return; stk_free(m->val); stk_free(m->min); free(m);}
void minstack_push(MinStack* m,int x){ stk_push(m->val,x); int cur = stk_empty(m->min)? x : stk_top(m->min); stk_push(m->min, x < cur ? x : cur); }
int minstack_pop(MinStack* m){ if(stk_empty(m->val)) return INT_MIN; stk_pop(m->min); return stk_pop(m->val); }
int minstack_top(MinStack* m){ return stk_top(m->val); }
int minstack_getMin(MinStack* m){ return stk_top(m->min); }

int main(){ MinStack* ms=minstack_new(8); minstack_push(ms,3); minstack_push(ms,5); minstack_push(ms,2); printf("min=%d\n", minstack_getMin(ms)); minstack_pop(ms); printf("min=%d\n", minstack_getMin(ms)); minstack_free(ms); return 0; }
